class.description:
[SourcePPVPK] exposes a first-cut wrapper over SourcePP's VPK support for scripts.
It can open existing VPK archives, create new ones, inspect files, read file contents, queue changes, and bake the archive back to disk.
[codeblock]
var vpk := SourcePPVPK.new()
if vpk.open("user://pak01_dir.vpk") != OK:
	return

for path in vpk.get_files():
	print(path)

var data := vpk.read_file("scripts/gameinfo.txt")
vpk.add_file_from_buffer("scripts/copied.bin", data)
vpk.bake()
[/codeblock]
